<template><el-drawer v-model="visible" :title="document?.title||'文档预览'" size="min(850px,95vw)" @closed="clear"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="document"><div class="ps-toolbar"><span>内容版本 {{document.contentVersion}}</span><span v-if="document.mimeType==='application/pdf'&&!document.pageCount" class="ps-muted">页数待解析</span><el-input-number v-if="document.pageCount" v-model="page" :min="1" :max="document.pageCount||1000000" aria-label="预览页码" @change="load"/><el-button :loading="loading" @click="load">刷新</el-button><el-button :disabled="loading" @click="download">下载原文件</el-button><el-button :disabled="loading||(!pdfBlob&&text===undefined&&!imageUrl)" @click="openWindow">新窗口查看当前页</el-button><el-button @click="zoom=Math.max(50,zoom-25)" :disabled="zoom<=50">缩小</el-button><span>{{zoom}}%</span><el-button @click="zoom=Math.min(200,zoom+25)" :disabled="zoom>=200">放大</el-button></div><div v-loading="loading" class="preview-body"><pre v-if="text!==undefined" class="ps-pre" :style="{fontSize:14*zoom/100+'px'}">{{text}}</pre><img v-else-if="imageUrl" :src="imageUrl" :alt="`${document.title} 第 ${page} 页`" :style="{width:zoom+'%'}"/><PdfPage v-else-if="pdfBlob" :blob="pdfBlob" :zoom="zoom" :anchor="initialAnchor"/><el-empty v-else-if="!loading" description="没有可预览内容"/></div></template></el-drawer></template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue'
import { downloadDocument,getDocumentContent, getDocumentPage } from '@/api/paismart/documents'
import type { Document } from '@/types/paismart'
import { errorText } from '../../composables/usePage'
import PdfPage from './PdfPage.vue'
const props=defineProps<{modelValue:boolean;document?:Document;initialPage?:number;initialAnchor?:string}>(),emit=defineEmits<{ 'update:modelValue':[boolean] }>()
const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)}),page=ref(1),zoom=ref(100),loading=ref(false),error=ref(''),text=ref<string>(),imageUrl=ref(''),pdfBlob=shallowRef<Blob>()
let controller:AbortController|undefined,serial=0,objectUrl=''
function clear(){serial++;controller?.abort();if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl='';text.value=undefined;imageUrl.value='';pdfBlob.value=undefined}
async function load(){if(!props.document)return;clear();const current=serial;controller=new AbortController();loading.value=true;error.value='';try{const doc=props.document;const blob=doc.pageCount?(await getDocumentPage(doc.id,page.value,doc.contentVersion,controller.signal)):(await getDocumentContent(doc.id,doc.contentVersion,controller.signal));if(current!==serial)return;if(blob.type==='application/json'){const body=JSON.parse(await blob.text());throw new Error(body.msg||'文档预览请求未完成')}else if(blob.type.startsWith('text/plain')){const value=await blob.text();if(current===serial)text.value=value}else if(blob.type==='application/pdf'||blob.type.startsWith('image/')){objectUrl=URL.createObjectURL(blob);if(blob.type==='application/pdf')pdfBlob.value=blob;else imageUrl.value=objectUrl}else throw new Error('该内容类型不允许在页面内预览，请使用受控下载')}catch(e){if(current===serial&&!controller.signal.aborted)error.value=errorText(e)}finally{if(current===serial)loading.value=false}}
function openWindow(){let url=objectUrl;if(text.value!==undefined)url=URL.createObjectURL(new Blob([text.value],{type:'text/plain;charset=UTF-8'}));else if(pdfBlob.value)url=URL.createObjectURL(pdfBlob.value);if(!url)return;window.open(url,'_blank','noopener,noreferrer');if(url!==objectUrl)setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function download(){if(!props.document)return;error.value='';try{const blob=await downloadDocument(props.document.id);const url=URL.createObjectURL(blob);const a=window.document.createElement('a');a.href=url;a.download=props.document.filename||props.document.title;a.click();setTimeout(()=>URL.revokeObjectURL(url),0)}catch(e){error.value=errorText(e)}}
watch(()=>[props.modelValue,props.document?.id,props.document?.contentVersion],()=>{if(props.modelValue){page.value=props.initialPage||1;zoom.value=100;void load()}else clear()})
onBeforeUnmount(clear)
</script>
<style scoped>.preview-body{overflow:auto;min-height:200px}.preview-body img{display:block;max-width:none}.pdf-frame{width:100%;height:72vh;border:0}</style>
